/// <summary>
/// The <c>AVAWHSProcessGuideDoChangePrinterStep</c> represents a step that change the printer.
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuideDoChangePrinterStep))
]
class AVAWHSProcessGuideDoChangePrinterStep extends ProcessGuideStepWithoutPrompt
{
}

Method.Source:
protected void doExecute()
{
    WhsrfPassthrough    pass;
    WHSUserId           userId;
    AVAPrinterCode      printerCode;

    pass        = controller.parmSessionState().parmPass();
    userId      = pass.lookupStr(ProcessGuideDataTypeNames::UserId);
    printerCode = pass.lookupStr(ProcessGuideDataTypeNames::AVAPrinterCode);

    this.validatePrinterForUser(userId, printerCode);
    this.updatePrinter(userId, printerCode);
    this.addChangeWarehouseProcessCompletionMessage();

    super();
}

/// <summary>
/// Update Printer in the session.
/// </summary>
/// <param name="_userId">
/// User id of the session.
/// </param>
/// <param name="_printerCode">
/// Printer code to be set into session.
/// </param>
protected void updatePrinter(WHSUserId _userId, AVAPrinterCode _printerCode)
{
    WHSWorkUserSession::avaUpdatePrinter(_userId, _printerCode);
}

private void addChangeWarehouseProcessCompletionMessage()
{ 
    ProcessGuideMessageData messageData = ProcessGuideMessageData::construct();

    messageData.message = "@NDX:AVASuccessfullPrinterChange";
    messageData.level   = WHSRFColorText::Success;

    navigationParametersFrom = ProcessGuideNavigationParameters::construct();
    navigationParametersFrom.messageData = messageData;
}

private void validatePrinterForUser(WHSUserId _userId, AVAPrinterCode _printerCode)
{ 
    if (!AVAWHSWorkUserPrinter::exist(_userId, _printerCode))
    { 
        throw error("@NDX:AVANoAssignedPrinterUser");
    }
}
